import React, { useState, useEffect } from "react";
import Login from "./components/login";
import IncomeCategory from "./components/IncomeCategory";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";
import Dashboard from "./components/Dashboard";
import Preview from "./components/Preview";
import Questionnaire from "./components/Questionnaire";

function App() {
  const [step, setStep] = useState("login");

  const [data, setData] = useState({
    income: "",
    categories: [],
    priorities: {},
    limits: {},
    questionnaire: {}
  });

  // ✅ Check if user already exists
  useEffect(() => {
    const user = JSON.parse(localStorage.getItem("user"));
    const savedData = JSON.parse(localStorage.getItem("formData"));

    if (user && savedData) {
      setData(savedData);
      setStep("login"); // still show login first
    }
  }, []);

  // ✅ LOGIN HANDLER
  const handleLogin = (userData) => {
    const existingUser = JSON.parse(localStorage.getItem("user"));

    // Save user
    localStorage.setItem("user", JSON.stringify(userData));

    const savedData = JSON.parse(localStorage.getItem("formData"));

    if (existingUser && savedData) {
      // ✅ Existing user → go to dashboard
      setData(savedData);
      setStep("dashboard");
    } else {
      // ✅ New user → start setup
      setStep("income");
    }
  };

  // ✅ SAVE DATA EVERY STEP
  const updateData = (newData) => {
    const updated = { ...data, ...newData };
    setData(updated);
    localStorage.setItem("formData", JSON.stringify(updated));
  };

  return (
    <>
      {step === "login" && (
        <Login onLogin={handleLogin} />
      )}

      {step === "income" && (
        <IncomeCategory
          initialValue={data.income}
          onNext={(val) => {
            updateData({ income: val });
            setStep("questionnaire");
          }}
        />
      )}

      {step === "questionnaire" && (
        <Questionnaire
          data={data}
          updateData={updateData}
          onNext={(answers) => {
            updateData({ questionnaire: answers });
            setStep("priority");
          }}
          onBack={() => setStep("income")}
        />
      )}

      {step === "priority" && (
        <SpendingPriority
          selectedCategories={data.categories}
          initialData={data.priorities}
          onNext={(priorities) => {
            updateData({ priorities });
            setStep("budget");
          }}
          onBack={() => setStep("questionnaire")}
        />
      )}

      {step === "budget" && (
        <BudgetLimits
          selectedCategories={data.categories}
          limits={data.limits}
          updateData={updateData}
          onNext={(limits) => {
            updateData({ limits });
            setStep("preview");
          }}
          onBack={() => setStep("priority")}
        />
      )}

      {step === "preview" && (
        <Preview
          data={data}
          updateData={updateData}
          onEdit={() => setStep("income")}
          onConfirm={() => setStep("dashboard")}
        />
      )}

      {step === "dashboard" && (
        <Dashboard />
      )}
    </>
  );
}

export default App;
